import{_ as l,o,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"CDS Jewel -- Hadoop over Ceph RGW","description":"","frontmatter":{"title":"CDS Jewel -- Hadoop over Ceph RGW","date":"2015-08-04T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","Hadoop","RGW","Distributed Storage","Performance Testing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Hadoop_over_Ceph_RGW.md","filePath":"posts/2015/CDS_Jewel_--_Hadoop_over_Ceph_RGW.md","lastUpdated":1780459816000}'),a={name:"posts/2015/CDS_Jewel_--_Hadoop_over_Ceph_RGW.md"};function r(s,i,p,n,g,_){return o(),e("div",null,[...i[0]||(i[0]=[t("<p>会议纪要：</p><p><strong>会议主题</strong>： Hadoop over Ceph RGW 状态更新</p><p><strong>会议时间</strong>： 未提及</p><p><strong>参会人员</strong>： Patrick、Yawn、Jen、Earning（远程）</p><p><strong>会议内容</strong>：</p><p><strong>1. Hadoop over Ceph RGW 设计回顾</strong></p><ul><li>该方案包括三个主要组件：Rgw Skidaway FS（Hadoop 兼容文件系统插件）、Rgw Skidaway Web Proxy（基于 Restful 服务的代理）、Rgw Skidaway with SSD Cache（使用 SSD 缓存的后端存储）。</li><li>设计流程：调度器请求数据位置，Rgw Skidaway Web Proxy 返回最近的数据节点，调度器在数据节点附近的服务器上分配任务，任务尝试从最近的数据节点访问数据。</li></ul><p><strong>2. 自 Infiniscale 以来更新</strong></p><ul><li><strong>Rgw Skidaway Web Proxy</strong>：已完成基于 Pass whiskey 模块的演示，可以通过 Restful 请求获取数据位置。</li><li><strong>Rgw Skidaway File System</strong>：已完成 70% 的代码开发，实现了与多个 Rgw Skidaway 实例的通信，并添加了块级位置信息，提高了读取性能。</li><li><strong>性能测试</strong>：与 HDFS 和 Swift 进行了基准性能测试，Swift 读取性能比 HDFS 低约 20%。</li></ul><p><strong>3. Rgw Skidaway File System 详细更新</strong></p><ul><li>新的文件系统 URL 将以 GW 前缀开头，可以使用该协议让 Hadoop 访问 Rgw Skidaway 集群。</li><li>已添加块级概念，基于块级位置信息提高读取性能。</li><li>存在问题：对于大于 5GB 的对象，存在零字节清单文件和大量小块，需要进一步解决。</li></ul><p><strong>4. Rgw Skidaway Proxy 详细更新</strong></p><ul><li>使用 Lister API 获取清单文件，查找每个块的节点位置。</li><li>使用 Oil API 跟踪 crush map，获取每个块的节点位置。</li><li>根据节点位置查找最近的 Rgw Skidaway 实例。</li></ul><p><strong>5. Rgw Skidaway File System 性能测试</strong></p><ul><li>使用 HDFS 和 Swift 进行了基准性能测试，Swift 读取性能比 HDFS 低约 20%。</li><li>分析了性能差异的原因，发现 Swift 重命名操作较为复杂。</li></ul><p><strong>6. 下一步计划</strong></p><ul><li>完成代码开发，进行基准性能测试。</li><li>解决大于 5GB 对象的零字节清单文件和小块问题。</li><li>研究复制实现，以解决性能问题。</li><li>将代码开源。</li></ul><p><strong>7. 其他讨论</strong></p><ul><li>讨论了禁用桶索引功能以提高性能的可能性。</li><li>讨论了网络瓶颈的可能性。</li><li>讨论了增加 Rgw Skidaway 与后端之间的连接数以提高性能的可能性。</li></ul><p><strong>行动计划</strong>：</p><ul><li>Yawn 和 Jen 继续开发代码。</li><li>Earning 进行基准性能测试。</li><li>研究复制实现和性能问题。</li><li>将代码开源。</li></ul>",21)])])}const w=l(a,[["render",r]]);export{S as __pageData,w as default};
